import sqlite3
import os
import hashlib
import hmac
import time
from functools import wraps
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = os.environ.get('DATABASE_PATH', '/var/app/data/users.db')
API_SECRET = os.environ['API_SECRET']

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_api_signature(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        timestamp = request.headers.get('X-Timestamp', '')
        signature = request.headers.get('X-Signature', '')
        if not timestamp or not signature:
            return jsonify({'error': 'Missing auth headers'}), 401
        try:
            ts_float = float(timestamp)
        except (ValueError, TypeError):
            return jsonify({'error': 'Invalid timestamp'}), 401
        if abs(time.time() - ts_float) > 300:
            return jsonify({'error': 'Request expired'}), 401
        expected = hmac.new(
            API_SECRET.encode(),
            f"{request.method}:{request.path}:{timestamp}".encode(),
            hashlib.sha256
        ).hexdigest()
        if not hmac.compare_digest(expected, signature):
            return jsonify({'error': 'Invalid signature'}), 401
        return f(*args, **kwargs)
    return decorated

class QueryBuilder:
    """Safe query builder that uses parameterized queries."""

    def __init__(self, table):
        self._table = self._validate_table(table)
        self._conditions = []
        self._params = []
        self._order = None
        self._limit = None

    @staticmethod
    def _validate_table(table):
        allowed = {'users', 'sessions', 'audit_log', 'permissions'}
        if table not in allowed:
            raise ValueError(f"Invalid table: {table}")
        return table

    def where(self, column, operator, value):
        """Add a WHERE condition with parameterized value."""
        allowed_columns = {
            'users': ['id', 'username', 'email', 'role', 'status', 'created_at', 'department'],
            'sessions': ['id', 'user_id', 'token', 'expires_at'],
            'audit_log': ['id', 'user_id', 'action', 'timestamp'],
            'permissions': ['id', 'user_id', 'resource', 'level']
        }
        allowed_ops = {'=', '!=', '<', '>', '<=', '>=', 'LIKE', 'IN'}

        if column not in allowed_columns.get(self._table, []):
            raise ValueError(f"Invalid column: {column}")
        if operator.upper() not in allowed_ops:
            raise ValueError(f"Invalid operator: {operator}")

        if operator.upper() == 'IN':
            if isinstance(value, (list, tuple)):
                placeholders = ','.join(['?'] * len(value))
                self._conditions.append(f"{column} IN ({placeholders})")
                self._params.extend(value)
            else:
                self._conditions.append(f"{column} IN (?)")
                self._params.append(value)
        else:
            self._conditions.append(f"{column} {operator} ?")
            self._params.append(value)
        return self

    def order_by(self, column, direction='ASC'):
        allowed_columns = {
            'users': ['id', 'username', 'email', 'role', 'status', 'created_at', 'department'],
            'sessions': ['id', 'user_id', 'expires_at'],
            'audit_log': ['id', 'timestamp'],
            'permissions': ['id', 'user_id']
        }
        if column not in allowed_columns.get(self._table, []):
            raise ValueError(f"Invalid order column: {column}")
        if direction.upper() not in ('ASC', 'DESC'):
            raise ValueError(f"Invalid direction: {direction}")
        self._order = f"{column} {direction.upper()}"
        return self

    def limit(self, n):
        self._limit = int(n)
        return self

    def build(self):
        query = f"SELECT * FROM {self._table}"
        if self._conditions:
            query += " WHERE " + " AND ".join(self._conditions)
        if self._order:
            query += f" ORDER BY {self._order}"
        if self._limit:
            query += f" LIMIT {self._limit}"
        return query, self._params

    def execute(self, db):
        query, params = self.build()
        return db.execute(query, params).fetchall()


def parse_search_filters(filter_string):
    """Parse a filter string like 'role:admin,status:active' into conditions."""
    filters = []
    if not filter_string:
        return filters
    for part in filter_string.split(','):
        if ':' in part:
            key, value = part.split(':', 1)
            filters.append((key.strip(), value.strip()))
    return filters


def apply_department_scope(query_builder, requesting_user):
    """Apply row-level security based on user's department."""
    if requesting_user['role'] == 'admin':
        return query_builder
    # Non-admins can only see users in their department
    query_builder.where('department', '=', requesting_user['department'])
    return query_builder


@app.route('/api/users/search', methods=['GET'])
@verify_api_signature
def search_users():
    """Search users with filters. Supports: role, status, department."""
    db = get_db()

    # Get requesting user from session
    session_token = request.headers.get('X-Session-Token')
    if not session_token:
        return jsonify({'error': 'No session'}), 401

    session = db.execute(
        "SELECT user_id FROM sessions WHERE token = ? AND expires_at > ?",
        (session_token, time.time())
    ).fetchone()
    if not session:
        return jsonify({'error': 'Invalid session'}), 401

    requesting_user = db.execute(
        "SELECT * FROM users WHERE id = ?", (session['user_id'],)
    ).fetchone()
    if not requesting_user:
        return jsonify({'error': 'User not found'}), 401

    # Build query
    qb = QueryBuilder('users')

    # Apply filters from query string
    filter_str = request.args.get('filters', '')
    filters = parse_search_filters(filter_str)

    for col, val in filters:
        if col in ('role', 'status', 'department'):
            qb.where(col, '=', val)

    # Apply department-level access control
    apply_department_scope(qb, requesting_user)

    # Apply ordering and limit
    order_col = request.args.get('order_by', 'created_at')
    order_dir = request.args.get('order_dir', 'DESC')
    try:
        qb.order_by(order_col, order_dir)
    except ValueError:
        pass

    limit_val = request.args.get('limit', '50')
    try:
        qb.limit(min(int(limit_val), 200))
    except (ValueError, TypeError):
        qb.limit(50)

    try:
        results = qb.execute(db)
        # Strip sensitive fields before returning
        safe_fields = ['id', 'username', 'email', 'role', 'status', 'department', 'created_at']
        users = [{k: dict(r)[k] for k in safe_fields if k in dict(r)} for r in results]
        return jsonify({'users': users})
    except Exception:
        return jsonify({'error': 'Query failed'}), 500


@app.route('/api/users/<int:user_id>/permissions', methods=['GET'])
@verify_api_signature
def get_permissions(user_id):
    """Get permissions for a specific user."""
    db = get_db()

    session_token = request.headers.get('X-Session-Token')
    if not session_token:
        return jsonify({'error': 'No session'}), 401

    session = db.execute(
        "SELECT user_id FROM sessions WHERE token = ? AND expires_at > ?",
        (session_token, time.time())
    ).fetchone()
    if not session:
        return jsonify({'error': 'Invalid session'}), 401

    requesting_user = db.execute(
        "SELECT * FROM users WHERE id = ?", (session['user_id'],)
    ).fetchone()
    if not requesting_user:
        return jsonify({'error': 'User not found'}), 401

    # Authorization: only admins or the user themselves can view permissions
    if requesting_user['role'] != 'admin' and requesting_user['id'] != user_id:
        return jsonify({'error': 'Forbidden'}), 403

    qb = QueryBuilder('permissions')
    qb.where('user_id', '=', user_id)
    results = qb.execute(db)
    return jsonify({'permissions': [dict(r) for r in results]})


